#!/bin/bash
# Prune old generations. keep must be a positive integer; otherwise nothing is deleted.
valid_keep() { [[ $1 =~ ^[1-9][0-9]*$ ]]; }

# read_keep <conf>: print keep value from conf (empty if absent).
read_keep() { sed -n 's/^keep=\([^[:space:]]*\)[[:space:]]*$/\1/p' "$1" | tail -n 1; }

# prune_local <dir> <name> <keep>: remove name.N where N > keep.
prune_local() {
  local dir=$1 name=$2 keep=$3 f n
  valid_keep "$keep" || { echo "prune: invalid keep '$keep', nothing deleted" >&2; return 1; }
  for f in "$dir/$name".*; do
    [ -e "$f" ] || continue
    n=${f#"$dir/$name".}
    [[ $n =~ ^[0-9]+$ ]] || continue
    [ "$((10#$n))" -gt "$keep" ] && rm -f -- "$f"
  done
}

# prune_archive <archive dir> <name> <keep>: keep only the newest <keep> name.<YYYYMMDD>.
prune_archive() {
  local dir=$1 name=$2 keep=$3 f s i=0
  valid_keep "$keep" || { echo "prune: invalid keep '$keep', nothing deleted" >&2; return 1; }
  local -a stamps=()
  for f in "$dir/$name".*; do
    [ -e "$f" ] || continue
    s=${f#"$dir/$name".}
    [[ $s =~ ^[0-9]{8}$ ]] && stamps+=("$s")
  done
  [ "${#stamps[@]}" -gt 0 ] || return 0
  while read -r s; do
    i=$((i + 1))
    [ "$i" -gt "$keep" ] && rm -f -- "$dir/$name.$s"
  done < <(printf '%s\n' "${stamps[@]}" | sort -ru)
  return 0
}

