}


# prune_archive <archive dir> <name> <keep>: keep only the newest <keep> name.<YYYYMMDD>; others untouched.
prune_archive() {
  local archive=$1 name=$2 keep=$3 f s files=() i
  for f in "$archive/$name".*; do
    s=${f#"$archive/$name".}
    case $s in [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]) files+=("$f") ;; esac
  done
  # glob order is ascending; dates are fixed width, so the oldest come first
  for ((i = 0; i < ${#files[@]} - keep; i++)); do rm -f -- "${files[i]}"; done
  return 0
}

